/**
 * UploadFiles queues local files and folders for parentID (empty for the
 * root) in an account ("" is the account on screen): the account whose
 * folder was chosen, even if another is on screen by the time the files
 * are picked. A folder is walked here and queued file by file, each
 * carrying its path relative to the folder's parent so the tree is
 * recreated on the server. Dotfiles (.DS_Store and friends) and empty
 * folders are skipped. Paths are checked as they are added; the rest still
 * go in when one is rejected, and the error names every one that was.
 */
export function UploadFiles(account: string, paths: string[] | null, parentID: string): $CancellablePromise<$models.UploadTask[] | null> {
    return $Call.ByID(379961131, account, paths, parentID);
}

/**
 * Uploads lists every account's upload records, each account's oldest
 * first, including the ones an earlier session left in the journal. An
 * account whose session ended still lists what it was uploading.
 */
export function Uploads(): $CancellablePromise<$models.UploadTask[] | null> {
    return $Call.ByID(1532620493);
}

/**
 * ViewerIdentity scopes local reading positions to this window's account.
 */
export function ViewerIdentity(): $CancellablePromise<string> {
    return $Call.ByID(4020040753);
}

/**
 * ViewerList reads the opening account even while the main window browses another.
 */
export function ViewerList(req: $models.ListRequest): $CancellablePromise<$models.ListPage> {
    return $Call.ByID(730770663, req);
}

export function ViewerWindow(): $CancellablePromise<$models.ViewerWindowState> {
    return $Call.ByID(3136848639);
}

/**
 * WebDAV reads the WebDAV status and issued clients.
 */
export function WebDAV(): $CancellablePromise<$models.WebDAVInfo> {
    return $Call.ByID(700195940);
}
